import { expect, Journey, test } from './journey.js';

// Verifies: RUN-001
test("After losing the connection the page reconnects and catches up on what it missed", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, ["reader","author"], { logs: false });
  try {
    await j.goto("/");
    await j.mark("loaded");
    await expect(j.page.getByRole("status", { name: "Live connection", exact: true })).toHaveAttribute("data-connection", "open");
    await j.context.setOffline(true);
    j.use("author");
    await j.goto("/login");
    await j.page.getByLabel("Name", { exact: true }).fill("mirela");
    await j.page.getByLabel("Password", { exact: true }).fill("strata-dev-mirela");
    await j.page.getByRole("button", { name: "Sign in", exact: true }).click();
    await expect(j.page.getByRole("heading", { name: "Writing desk", exact: true, level: 1 })).toBeVisible();
    await j.page.getByRole("link", { name: "Write a new article", exact: true }).click();
    await expect(j.page.getByRole("heading", { name: "New article", exact: true, level: 1 })).toBeVisible();
    await j.page.getByLabel("Title", { exact: true }).fill("While You Were Away");
    await j.page.getByLabel("Text", { exact: true }).fill("A first paragraph written by a test.\n\n## A heading\n\nAnd a second one.");
    await j.page.getByRole("button", { name: "Save draft", exact: true }).click();
    await j.expectText(j.page.getByRole("region", { name: "Messages", exact: true }), j.text("Draft saved."), undefined);
    await expect(j.page.getByRole("heading", { name: "Edit article", exact: true, level: 1 })).toBeVisible();
    await j.page.getByRole("button", { name: "Publish", exact: true }).click();
    await j.expectText(j.page.getByRole("region", { name: "Messages", exact: true }), j.text("Published."), undefined);
    j.use("reader");
    await j.expectNoText(null, j.text("While You Were Away"), undefined);
    await j.context.setOffline(false);
    await expect(j.page.getByRole("status", { name: "Live connection", exact: true })).toHaveAttribute("data-connection", "open", { timeout: 20000 });
    await expect(j.page.getByRole("heading", { name: "While You Were Away", exact: true })).toBeVisible();
    await j.expectNoReload("loaded");
    j.use("author");
    await j.page.getByRole("button", { name: "Unpublish", exact: true }).click();
    j.use("reader");
    await expect(j.page.getByRole("heading", { name: "While You Were Away", exact: true })).toHaveCount(0);
  } finally {
    await j.close();
  }
});
